"""Short course promo: curriculum, code concepts, native-size app, platform preview."""
from pathlib import Path
import hashlib,json,shutil,html
from plan_lab_settings import SETTINGS
ROOT=Path(__file__).resolve().parents[1];NAME='agent-sdk-short-promo-v4';P=ROOT/'presentations'/NAME;V=ROOT/'videos'/NAME
P.mkdir(parents=True,exist_ok=True);V.mkdir(parents=True,exist_ok=True)
shutil.copy2(ROOT/'presentations/agent-sdk-course-concepts-and-app-v4/cover.png',P/'cover.png')
shutil.copy2(ROOT/'videos/agent-sdk-bonus-course/reference-0.jpg',P/'platform.jpg')
slides=[]
def add(title,tag,body,segments,cls='',motion=None):slides.append(dict(title=title,tag=tag,body=body,segments=segments,cls=cls,motion=motion))
def cue(cid,text):return f'<span data-cue="{cid}">{text}</span>'
add('Claude Agent SDK','FREE COURSE','<img class="full" src="cover.png"><div class="invisible" data-cue="cover" style="left:100px;top:610px;width:1110px;height:145px"></div>',[('cover','Build your first Claude Agent SDK application with Luis Coco Enriquez.')],'cover')
groups=[('1–2','SDK foundations','What is the SDK? · Getting Started'),('3–4','Your first query()','Send a task · Invoke query()'),('5–6','The agent loop','Follow decisions · Practical loop example'),('7–8','Message types','Read SDK messages · Practical example'),('9–10','Context and compaction','Understand context · Practical example'),('11–13','Configure and control','Options · Models and effort · Turns and spending')]
cards=''.join(f'<article class="index-card"><small>LECTURES {a}</small><h2>{b}</h2><p>{c}</p></article>' for a,b,c in groups)
add('Your course at a glance','13 CORE LECTURES · 8 PRACTICAL EXAMPLES · 2 SECTIONS','<div class="index">'+cards+'</div><div class="bottom">'+cue('index','Core concepts paired with practical applications')+'</div>',[('index','Thirteen core lectures pair SDK foundations, query, the agent loop, messages, and context with practical examples. Then configure models, effort, turns, and spending.')])
concepts=[
 ('Start with a runnable project','LECTURES 1–2 · SDK FOUNDATIONS + GETTING STARTED','Understand the SDK','Embed the agent loop and tools in your own application.','Prepare the first example','Install the package, configure authentication, and choose a small workspace.','npm install @anthropic-ai/claude-agent-sdk\n\nimport { query } from\n  "@anthropic-ai/claude-agent-sdk";','Learn what the SDK provides, install it, and prepare a small workspace. The first example makes setup concrete.'),
 ('Send a task and follow the loop','LECTURES 3–6 · query() + AGENT LOOP','Start with one prompt','Ask a focused question that has a checkable answer.','Follow the work','The SDK yields messages while the model and tools work toward a result.','const run = query({\n  prompt: "What files are here?",\n  options: { cwd: "./sample-workspace" }\n});\nfor await (const message of run) {\n  console.log(message.type);\n}','Invoke query with a prompt and working directory. Follow its message stream as the model uses tools and produces an answer.'),
 ('Read messages and understand context','LECTURES 7–10 · MESSAGE TYPES + CONTEXT + COMPACTION','Separate progress from completion','Tool activity and assistant text are different from the final result.','Understand the working context','Learn how conversation history uses context and why compaction matters.','for await (const message of run) {\n  if (message.type === "result") {\n    console.log(message.subtype);\n  }\n}\n// History consumes context.\n// Compaction summarizes earlier history.','Distinguish progress messages from the final result. Then explore conversation context and compaction through practical examples.'),
 ('Choose how your agent runs','LECTURES 11–13 · OPTIONS + MODELS + EFFORT + LIMITS','Configure the application','Choose the model, effort and environment for the task.','Bound the experiment','Set turn and spending limits, then inspect the final outcome.','const options = {\n  cwd: "./sample-workspace",\n  allowedTools: ["Glob"],\n  maxTurns: 4,\n  maxBudgetUsd: 0.15\n};\n// Limits constrain this teaching example.','Use the options object to choose execution settings. Learn how models, effort, environment, turns, and spending limits affect your experiments.')]
for i,(title,tag,h1,p1,h2,p2,code,narration) in enumerate(concepts):
 body=f'<div class="concept"><div><article><h2>{h1}</h2><p>{p1}</p></article><article><h2>{h2}</h2><p>{p2}</p></article><p class="outcome" data-cue="concept-{i}">{title}</p></div><div class="code"><small>TYPESCRIPT · TEACHING EXCERPT</small><pre>{html.escape(code)}</pre></div></div>'
 add(title,tag,body,[(f'concept-{i}',narration)])
for id,title,desc,narration in [
 ('prompt','1 · Give the agent a focused task','Prompt → scoped workspace → Run query()','Here is the practical application at one hundred percent zoom. Enter the file-listing question and run it in the sample workspace.'),
 ('events','2 · Follow the SDK and tool activity','SDK messages → Glob discovery → assistant response','Inspect the actual SDK messages and Glob activity. The tool discovers files in the selected workspace before the answer is produced.'),
 ('result','3 · Verify the final result','Final status → answer → host reference','Check the final success status, then compare the returned file paths with the host reference. This connects the code to visible evidence.')]:
 add(title,'PRACTICAL EXAMPLE · NATIVE 100% BROWSER ZOOM',f'<img class="full" src="app/{id}.png"><div class="app-heading"><h1>{title}</h1><p data-cue="app-{id}">{desc}</p></div>',[(f'app-{id}',narration)],'app')
add('Start building with Claude Agent SDK','YOUR NEXT STEP','<div class="cta"><h2>Enroll in the free course</h2><p data-cue="cta">Explore the lessons and run your first practical example.</p><small>LUIS COCO ENRIQUEZ</small></div>',[('cta','Enroll in the free course and run your first practical example. Thank you for watching.')])
add('Explore the learning platform','SEPARATE COURSE PREVIEW','<img class="full" src="platform.jpg"><div class="invisible" data-cue="platform" style="left:200px;top:44px;width:1600px;height:72px"></div>',[('platform','To continue beyond this free course, explore the separate Claude Agent SDK course and its seventy-five-lab learning platform.')],'platform',{'file':f'presentations/{NAME}/platform-excerpt.mp4','rect':[0,0,1920,1080]})
css='''*{box-sizing:border-box}body{margin:0;color:#0c1744;background:#f1f8ff;font-family:Arial}.slide{width:1920px;height:1080px;padding:60px 72px;position:relative;overflow:hidden;display:none;background:radial-gradient(ellipse at 95% 0%,#e0f0ff,transparent 50%),#fcfdff}.active{display:block}.tag{font-size:23px;color:#087fff;font-weight:800;letter-spacing:1px}h1{font-size:57px;line-height:1.1;margin:26px 0 34px;letter-spacing:-1px}.index{display:grid;grid-template-columns:repeat(3,1fr);gap:25px;margin-top:48px}.index-card{border:1px solid #d2e6f8;border-radius:26px;background:#edf7ff;padding:30px;height:280px}.index-card:nth-child(3n+2){background:#f3edff}.index-card:nth-child(3n){background:#ecfbf4}small{font-size:22px;color:#087fff;font-weight:800}h2{font-size:34px;line-height:1.2;margin:22px 0}p{font-size:30px;line-height:1.4}.bottom{font-size:31px;margin-top:36px;font-weight:bold}.concept{display:grid;grid-template-columns:750px 1fr;gap:54px;margin-top:65px}.concept article{border:1px solid #d2e6f8;border-radius:24px;background:#eff7ff;padding:22px 30px;margin-bottom:28px}.concept article h2{margin:0 0 18px}.concept article p{margin:0}.outcome{font-size:29px;font-weight:bold;color:#087fff}.code{border-radius:26px;background:#102342;color:white;padding:40px;height:620px}.code small{color:#ffb282}pre{font:27px/1.65 Consolas,monospace;white-space:pre-wrap;margin-top:34px}.footer{position:absolute;bottom:28px;left:72px;right:72px;font-size:18px;color:#577493;display:flex;justify-content:space-between}.full{position:absolute;left:0;top:0;width:1920px;height:1080px;object-fit:contain}.invisible{position:absolute;opacity:0}.cover,.platform,.app{padding:0}.app-heading{position:absolute;left:0;right:0;top:0;height:148px;background:#081c36;color:#fff;padding:20px 48px}.app-heading h1{font-size:44px;margin:0 0 14px}.app-heading p{font-size:29px;color:#ffb282;display:inline-block;margin:0}.app .footer{display:none}.cta{margin:120px auto;background:#eaf6ff;border:1px solid #cbe4f8;border-radius:40px;padding:60px;text-align:center}.cta h2{font-size:74px;color:#087fff}.cta p{display:inline-block;font-size:36px}.cta small{display:block;margin-top:45px}'''
css+='''.app-heading{left:0;right:auto;top:24px;width:270px;height:auto;min-height:440px;background:#eaf4ff;color:#0c1744;padding:24px;border-radius:0 22px 22px 0}.app-heading h1{font-size:30px;line-height:1.25;margin:0 0 32px;letter-spacing:0}.app-heading p{font-size:25px;line-height:1.45;color:#a84018;display:block}.app-heading:after{content:"100% BROWSER ZOOM";display:block;font-size:17px;font-weight:bold;line-height:1.5;color:#087fff;margin-top:38px}'''
page='<!doctype html><meta charset="utf-8"><title>Claude Agent SDK · Short Promo</title><style>'+css+'</style>'
for i,s in enumerate(slides):page+=f'<section class="slide {s["cls"]} {"active" if i==0 else ""}" data-slide="{i+1}">'+('' if s['cls'] in ['cover','platform','app'] else f'<div class="tag">{s["tag"]}</div><h1>{s["title"]}</h1>')+s['body']+('' if s['cls'] in ['cover','platform'] else f'<footer class="footer"><span>CLAUDE AGENT SDK · CORE CONCEPTS & PRACTICE</span><span>{i+1:02} / {len(slides):02}</span></footer>')+'</section>'
source=P/'promo.html';source.write_text(page,encoding='utf8');(P/'storyboard.json').write_text(json.dumps(slides,indent=2))
(V/'narration-script.txt').write_text('\n\n'.join(f'{i+1}. {s["title"]}\n'+' '.join(t for _,t in s['segments']) for i,s in enumerate(slides)),encoding='utf8')
geometry=P/'.build/video/slides/geometry.json'
if geometry.exists():
 g=json.loads(geometry.read_text());rows=[]
 for i,s in enumerate(slides):
  row={'slide':i+1,'segments':[{'id':cid,'text':t,'target':{'textRects':[next(r['rect'] for r in g[i]['rects'] if r['id']==cid)],'paragraphGroups':[[0]]}} for cid,t in s['segments']]}
  if s['motion']:row['motion']=s['motion']
  rows.append(row)
 (V/'narration-plan.json').write_text(json.dumps({'project':NAME,'title':'Claude Agent SDK — Short Course Promo','mediaPrefix':'Claude-Agent-SDK-Short-Promo','outputFile':'Claude-Agent-SDK-Short-Promo.mp4','presentation':source.relative_to(ROOT).as_posix(),'presentationSha256':hashlib.sha256(source.read_bytes()).hexdigest(),'settings':SETTINGS,'slides':rows},indent=2))
 print('11-scene narration plan ready.')
else:print('11 scenes authored; capture next.')
